import java.util.*;

class Solution {
  private int b;
  private Map<Long, Integer> memo;

  public int maxHappyGroups(int batchSize, int[] groups) {
    b = batchSize;
    int[] cnt = new int[b];
    for (int g : groups) cnt[g % b]++;
    int answer = cnt[0];
    cnt[0] = 0;
    long state = 0;
    for (int i = 1; i < b; i++) state |= (long) cnt[i] << (5 * (i - 1));
    memo = new HashMap<>();
    return answer + dfs(state, 0);
  }

  private int dfs(long state, int remainder) {
    if (state == 0) return 0;
    long key = (state << 4) | remainder;
    Integer cached = memo.get(key);
    if (cached != null) return cached;
    int best = 0;
    for (int r = 1; r < b; r++) {
      int count = (int) ((state >> (5 * (r - 1))) & 31);
      if (count == 0) continue;
      long next = state - (1L << (5 * (r - 1)));
      best = Math.max(best, (remainder == 0 ? 1 : 0) + dfs(next, (remainder + r) % b));
    }
    memo.put(key, best);
    return best;
  }
}
